import { useRef, useState } from "react";
import styles from "./cart.module.less";
import CartItem, { CartItemProps, ItemInCart } from "./cart-item";
import { ECommerceHelper, isTruthy, multipleClassNames } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import {
  OutlineButton,
  OutlineButtonLink,
  PrimaryButton,
  PrimaryButtonLink,
} from "@/core/components/primitives/parks-button/parks-button";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";
import { useProducts } from "@/core/hooks/product-hooks";
import { WebshopProductType } from "@parksandresorts/webapiproxy-types";
import { SummaryTotal, SummaryTotalPropsWithPrice } from "@/core/components/primitives/summary-total/summary-total";

type ContinueShoppingButtonProps = {
  continueShoppingLink: { internalLink: { slug: string }; title: string } | undefined;
  continueShoppingLabel: string | undefined;
  onContinueShopping?: (evt: React.MouseEvent) => void;
  variant?: "ghost" | "primary";
};
export const ContinueShoppingButton = ({
  continueShoppingLink,
  continueShoppingLabel,
  onContinueShopping,
  variant = "ghost",
}: ContinueShoppingButtonProps) => {
  const slug = continueShoppingLink?.internalLink?.slug;
  const continueLabel = continueShoppingLink?.title ?? continueShoppingLabel;

  const ButtonVariantLink = variant === "primary" ? PrimaryButtonLink : OutlineButtonLink;
  const ButtonVariant = variant === "primary" ? PrimaryButton : OutlineButton;

  return (
    <span onClick={onContinueShopping}>
      {slug ? (
        <ButtonVariantLink className={styles.continueShoppingButton} label={continueLabel} url={slug} isFullWidth />
      ) : (
        <ButtonVariant className={styles.continueShoppingButton} label={continueShoppingLabel} isFullWidth />
      )}
    </span>
  );
};

const BlackWeekOnly = ({ totalSumInclVat }: { totalSumInclVat: number }) => {
  const { t } = useTranslation();

  const [isExpanded, setIsExpanded] = useState(false);
  function getQuantityText(totalSumInclVat: number) {
    return `${Math.floor(totalSumInclVat / 450)} st`;
  }
  return (
    <>
      <div className={styles.bwWrapper}>
        <img className={styles.bwImg} alt="Text Black week" src="/images/black-week/GLT_BW_BlackWeek.png" />
        <div className={styles.bwInnerWrapper}>
          <p data-contentful-label-id="BW_CART_TEXT" className={styles.bwText}>
            {t("BW_CART_TEXT", "Antal gratis åkband som ingår i ditt köp")}
          </p>
          <span className={styles.bwQuantity}>{getQuantityText(totalSumInclVat)}</span>
        </div>
        <button
          className={styles.bwReadMore}
          onClick={() => setIsExpanded(!isExpanded)}
          aria-expanded={isExpanded}
          aria-controls="readMoreContent"
          data-contentful-label-id="BW_CART_READ_MORE_LABEL & BW_CART_READ_LESS_LABEL"
        >
          {isExpanded
            ? t("BW_CART_READ_LESS_LABEL", "Läs mindre")
            : t("BW_CART_READ_MORE_LABEL", "Varför får jag gratis åkband?")}
        </button>
        <div
          data-contentful-label-id="BW_CART_READ_MORE_TEXT"
          id="readMoreContent"
          style={{ display: isExpanded ? "block" : "none" }}
          aria-hidden={!isExpanded}
        >
          {t(
            "BW_CART_READ_MORE_TEXT",
            "För varje 450 kronor du handlar för får du automatiskt ett åkband med på köpet! Gäller hela Black week till och med 29/11.",
          )}
        </div>
      </div>
    </>
  );
};

export type CartProps = Pick<CartItemProps, "deleteCartItem" | "updateCartItemQuantity"> & {
  hideContinueShopping?: boolean;
  hideGoToCheckout?: boolean;
  hideHeadline?: boolean;
  enableBlackWeekOffer?: boolean;
  hideTotalSum?: boolean;
  hideShippingProducts?: boolean;

  onGoToCheckout?: (evt: React.MouseEvent) => void;
  onContinueShopping?: (evt: React.MouseEvent) => void;
  checkoutUrl: string | undefined;
  isDisabled: boolean;
  totalSumInclVat: number;
  originalProductSummaryAmount?: SummaryTotalPropsWithPrice["originalProductSummaryAmount"];
  products: Array<ItemInCart>;

  innerWrapperClassName?: string;
};
export default function Cart({
  hideContinueShopping,
  hideGoToCheckout,
  hideHeadline,
  hideTotalSum,
  hideShippingProducts,
  enableBlackWeekOffer,
  onContinueShopping,
  onGoToCheckout,
  checkoutUrl,
  isDisabled,
  products,
  totalSumInclVat,
  originalProductSummaryAmount,

  deleteCartItem,
  updateCartItemQuantity,

  innerWrapperClassName,
}: CartProps) {
  const cartLabel = ECommerceHelper.jetshop?.cartLabel;
  const toCheckoutLabel = ECommerceHelper.jetshop?.jetshopCheckoutUrl?.title;
  const continueShoppingLabel = ECommerceHelper.jetshop?.continueShoppingLabel;
  const continueShoppingLink = ECommerceHelper.jetshop?.continueShoppingLink;
  const articleLabel = ECommerceHelper.jetshop?.cartArticleLabel;
  const articlesLabel = ECommerceHelper.jetshop?.cartArticlesLabel;
  const cartIsEmptyLabel = ECommerceHelper.jetshop?.cartIsEmptyLabel;
  const showContinueShopping = !hideContinueShopping;
  const showGoToCheckout = !hideGoToCheckout;
  const showHeadline = !hideHeadline;
  const showTotalSum = !hideTotalSum;

  const [announcement, setAnnouncement] = useState<string | null>(null);
  const itemRefs = useRef<Array<HTMLDivElement | null>>([]);
  const headingRef = useRef<HTMLDivElement | null>(null);

  const { productsById } = useProducts(products.map((item) => item.productId).filter(isTruthy));

  const productsWithoutShipping = products.filter(
    (p) => productsById.get(p.productId ?? 0)?.glkProduct.productType !== WebshopProductType.SHIPPING_FEE,
  );
  const filteredProducts = hideShippingProducts ? productsWithoutShipping : products;

  const handleAnnounceAndFocus = (msg: string | null) => {
    setAnnouncement(msg ? `${msg}` : null);

    // Delay focus until after live region update
    setTimeout(() => {
      // Find the first focusable cart item
      const nextItem = itemRefs.current.find((el) => el !== null);
      if (nextItem) {
        nextItem.focus();
      } else if (headingRef.current) {
        headingRef.current.focus();
      }
    }, 50);
  };

  const handleDeleteCartItem = (item: ItemInCart, announcementMsg?: string) => {
    deleteCartItem?.(item);

    if (announcementMsg) {
      handleAnnounceAndFocus(announcementMsg);
    }
  };

  const getCartLabel = (itemsInCart: number) => {
    if (itemsInCart > 0) {
      return `${cartLabel} (${itemsInCart} ${itemsInCart > 1 ? articlesLabel : articleLabel})`;
    }
    return `${cartLabel} ${cartIsEmptyLabel}`;
  };

  const totalItems = productsWithoutShipping.reduce((acc, { quantity }) => acc + quantity, 0);

  return (
    <div className={styles.cart}>
      <div className={multipleClassNames(styles.innerWrapper, innerWrapperClassName)}>
        {showHeadline && (
          <div ref={headingRef} className={multipleClassNames(styles.title, "heading-s")}>
            {getCartLabel(totalItems)}
          </div>
        )}
        <ul className={styles.list}>
          {filteredProducts.map((product, idx) => {
            return (
              <li key={String(product.id)} className={styles.listItem}>
                <CartItem
                  ref={(el) => (itemRefs.current[idx] = el)}
                  item={product}
                  isDisabled={isDisabled}
                  deleteCartItem={handleDeleteCartItem}
                  updateCartItemQuantity={updateCartItemQuantity}
                />
              </li>
            );
          })}
        </ul>
        {enableBlackWeekOffer && <BlackWeekOnly totalSumInclVat={Number(totalSumInclVat)} />}
        {/* Important! Don't rely on `totalSumInclVat` alone to determine if we should show total price.
        It could be that the cart has 100% discount items making the total 0, but still having products in the cart. */}
        {totalItems > 0 && showTotalSum && (
          <SummaryTotal
            type="price"
            labelId="cartSummary"
            price={totalSumInclVat}
            originalProductSummaryAmount={originalProductSummaryAmount}
          />
        )}
      </div>
      {(showGoToCheckout || showContinueShopping) && (
        <div className={styles.bottomButtonWrapper}>
          {showGoToCheckout && (
            <span onClick={onGoToCheckout}>
              <PrimaryButtonLink
                label={toCheckoutLabel}
                isDisabled={isDisabled}
                url={!isDisabled ? checkoutUrl : undefined}
                className={styles.checkoutButton}
                isFullWidth
              />
            </span>
          )}
          {showContinueShopping && (
            <ContinueShoppingButton
              continueShoppingLink={continueShoppingLink}
              continueShoppingLabel={continueShoppingLabel}
              onContinueShopping={onContinueShopping}
            />
          )}
        </div>
      )}
      <SpokenText text={announcement || ""} ariaLive="assertive" />
    </div>
  );
}
